  "responsive": {
    "strategy": "One slide visible per viewport width at all breakpoints.",
    "breakpoints": {
      "compact": "Full-width slide with large touch targets.",
      "medium": "Full-width slide.",
      "large": "Full-width slide."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
