.cu-carousel {
  display: block;
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  overflow: hidden;
}

.cu-carousel__viewport {
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  min-block-size: calc(var(--cu-space-3) * 8);
}

.cu-carousel__controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cu-space-2);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border-block-start: 1px solid var(--cu-color-border-default);
}

.cu-carousel__control {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--cu-space-3);
  block-size: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  cursor: pointer;
}

.cu-carousel__control:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-carousel__position {
  font-size: 0.875em;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}
